CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade not null,role public.app_role not null,unique(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',avatar_url text not null default '',created_at timestamptz not null default now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_library_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.membership_plans(id uuid primary key default gen_random_uuid(),name text not null,price integer not null check(price>=0),description text not null default '',billing_period text not null default 'To be confirmed',timings text not null default 'To be confirmed',enabled boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now());
GRANT SELECT ON public.membership_plans TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.membership_plans TO authenticated; GRANT ALL ON public.membership_plans TO service_role;
ALTER TABLE public.membership_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_plans ON public.membership_plans FOR SELECT TO anon,authenticated USING(enabled);
CREATE POLICY admin_plans ON public.membership_plans FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.facilities(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',image_url text not null default '',enabled boolean not null default false,confirmed boolean not null default false,display_order integer not null default 0,created_at timestamptz not null default now());
GRANT SELECT ON public.facilities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.facilities TO authenticated; GRANT ALL ON public.facilities TO service_role;
ALTER TABLE public.facilities ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_facilities ON public.facilities FOR SELECT TO anon,authenticated USING(enabled AND confirmed);
CREATE POLICY admin_facilities ON public.facilities FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gallery_images(id uuid primary key default gen_random_uuid(),caption text not null default '',image_url text not null,enabled boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now());
GRANT SELECT ON public.gallery_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.gallery_images TO authenticated; GRANT ALL ON public.gallery_images TO service_role;
ALTER TABLE public.gallery_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_gallery ON public.gallery_images FOR SELECT TO anon,authenticated USING(enabled);
CREATE POLICY admin_gallery ON public.gallery_images FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.website_settings(id text primary key default 'main',hero_heading text not null default 'Your Space. Your Focus. Your Success.',hero_description text not null default 'A little less distraction. A lot more possibility. Find your focus at My Library – The Study Space in Gomti Nagar, Lucknow.',about text not null default 'Your ambitions deserve a space of their own. My Library – The Study Space is a dedicated study library in Gomti Nagar, Lucknow, created for students who want to make time for what matters.',address text not null default '3/7 Vastu Khand, Gomti Nagar, Lucknow, Uttar Pradesh, India',landmark text not null default 'Kopious Tower, Near Kathaauta Chauraha',phone text not null default '9450537777',phone_secondary text not null default '9415007722',email text not null default 'mylibrary.lucknow@gmail.com',opening_hours text not null default 'Please contact us to confirm opening hours.',instagram text not null default '',facebook text not null default '',hero_image text not null default '');
GRANT SELECT ON public.website_settings TO anon; GRANT SELECT,UPDATE ON public.website_settings TO authenticated; GRANT ALL ON public.website_settings TO service_role;
ALTER TABLE public.website_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.website_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.website_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.testimonials(id uuid primary key default gen_random_uuid(),name text not null,quote text not null,is_sample boolean not null default true,enabled boolean not null default true,created_at timestamptz not null default now());
GRANT SELECT ON public.testimonials TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.testimonials TO authenticated; GRANT ALL ON public.testimonials TO service_role;
ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_testimonials ON public.testimonials FOR SELECT TO anon,authenticated USING(enabled);
CREATE POLICY admin_testimonials ON public.testimonials FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.enquiries(id uuid primary key default gen_random_uuid(),student_name text not null,mobile text not null,email text not null default '',kind text not null check(kind in ('contact','membership')),plan_name text not null default '',preferred_shift text not null default '',message text not null default '',status text not null default 'New' check(status in ('New','Contacted','Converted','Rejected')),created_at timestamptz not null default now());
GRANT SELECT,UPDATE,DELETE ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_enquiries ON public.enquiries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX enquiries_date ON public.enquiries(created_at DESC); CREATE INDEX enquiries_status ON public.enquiries(status);
