CREATE POLICY admin_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='library-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='library-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='library-photos' AND public.has_role(auth.uid(),'admin'));